const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
export function createSocial(ctx){
 let avatar=null,avatarMount=0,account=null,voices=null,voiceError='',roast=null,roastKey='',variation=0,busy=false,recording=null,clip=null,clipURL='',clipPlace=null,loadId=0;
 const state=()=>ctx.get();
 const key=()=>{const {place,weather}=state();return place.latitude+','+place.longitude+':'+(weather?.current?.time||'')};
 function editorial(){const w=state().weather;if(!w)return {kind:'none',title:'Il meteo sta arrivando',text:'Le proposte si aggiornano con le condizioni della tua zona.'};const c=w.current;if(c.weather_code>=95)return {kind:'play',title:'Meteo Play',text:'Temporali nelle previsioni. Una pausa dal setup? Consulta le indicazioni ufficiali, senza improvvisare interventi elettrici.'};const h=w.hourly,i=h.time.findIndex(t=>t>=c.time),rain=i>=0&&h.precipitation_probability.slice(i,i+3).length===3&&h.precipitation_probability.slice(i,i+3).every(p=>p>=65);if(rain)return {kind:'cinema',title:'Meteo Cinema',text:'Probabilità di pioggia elevata nelle prossime tre ore. Atmosfera da film, coperta e programmi rimandati.'};if(c.temperature_2m>=30)return {kind:'play',title:'Meteo Play',text:'Fa caldo anche fuori dal gioco. Un promemoria per controllare la ventilazione del tuo setup.'};return {kind:'none',title:'Il cielo lascia scegliere te.',text:'Esplora Meteo Play e Meteo Cinema, anche senza aspettare la pioggia.'}}
 function fallback(){const w=state().weather;if(!w)return 'Il cielo si sta caricando. Tu intanto scegli la città.';const c=w.current;if(variation%3===1)return c.weather_code>=51?'Il cielo ha scritto una recensione umida dei tuoi programmi.':'Il cielo ha un piano. Tu hai aperto questa app.';if(variation%3===2)return 'Hai controllato il meteo più volte della tua agenda.';return c.weather_code>=95?'Il cielo oggi ha attivato gli effetti speciali.':c.temperature_2m>=30?'Fuori è un forno. Tu sei la modalità ventilata.':c.temperature_2m<8?'Il piumone ha argomenti migliori dei tuoi programmi.':c.weather_code>=51?'Il cielo ha disdetto anche i tuoi programmi immaginari.':c.weather_code<=2?'Il sole è uscito. Le tue scuse stanno sudando.':'Il cielo ha scelto il grigio. Tu puoi ancora cambiare outfit.'}
 function moduleCard(){const m=editorial();return `<section class="editorial ${m.kind}"><div class="editorial-tag">SCELTO DAL METEO · PROPOSTA EDITORIALE</div><h2>${m.title}</h2><p>${e(m.text)}</p><div class="module-links"><a href="#meteo-play">Meteo Play →</a><a href="#meteo-cinema">Meteo Cinema →</a></div></section>`}
 function home(){const {place,weather}=state();const text=roastKey===key()&&roast?roast.text:fallback();return `<div class="app-intro"><div><span class="eyebrow">IL TUO CIELO. ZERO FILTRI.</span><h1>${e(place.name)}</h1></div><button data-search-place>Cambia città</button></div><div class="bento"><section class="roast-card"><div class="roast-copy"><span class="tag">WEATHER ROAST</span><h2 id="roast-text">${e(text)}</h2><p class="small" id="roast-source">${roastKey===key()&&roast?.ai?'Testo generato con IA':state().aiReady?'Battuta editoriale · genera un roast con IA':'Battuta editoriale · IA non collegata'}</p><div class="roast-actions"><button class="button" id="share-roast">Condividi la card ↗</button><button id="generate-roast" ${busy?'disabled':''}>${busy?'Un momento…':state().aiReady?'Genera con IA':'Altra battuta'}</button></div><p class="small" id="roast-status" role="status"></p></div></section><section class="card"><span class="eyebrow">FUORI, ADESSO</span><p class="roast-temperature">${weather?Math.round(weather.current.temperature_2m)+'°':'—'}</p><p>${weather?e(ctx.description(weather.current.weather_code)):'Caricamento delle previsioni…'}</p><a href="#tendenze">Vedi previsioni e fonte →</a></section><section class="card"><span class="eyebrow">STESSO CIELO</span><h2 style="margin-top:18px">Cinque secondi dalla tua zona.</h2><p>Un vocale, un ultimo check-in. Nessun tracciamento in diretta.</p><a class="button" href="#voci">Apri la mappa social</a></section>${moduleCard()}</div><div class="module-links"><a href="#mondo">Esplora il pianeta 3D</a><a href="#community">Post e conversazioni</a><a href="#redazione">La tua redazione</a></div><details class="card"><summary>Dati meteo e fonti</summary>${ctx.weatherHTML()}</details>`}
 function avatarPage(){const a=account?.avatar||{bald:1,equipped:'none'},items=account?.items||[];return `<span class="eyebrow">IL TUO ALTER EGO</span><h1>Un piccolo te. Un altro cielo.</h1><div class="avatar-layout"><div id="avatar-stage" class="avatar-stage avatar-preview"></div><section><div class="card"><h2>Il tuo look</h2><button id="toggle-hair" aria-pressed="${!!a.bald}">${a.bald?'✓ Testa rasata':'Capelli corti'} · cambia</button><p class="small">${state().me?'Aspetto e accessori salvati sul tuo account.':'Accedi per salvare il tuo avatar.'}</p><button data-equip="none">Senza accessori</button></div>${[['headphones','Cuffie streaming','Invita 3 amici che completano il profilo.'],['microphone','Microfono da scrivania','Un drop da reclamare quando è prevista pioggia nella località scelta.']].map(([id,name,desc])=>`<div class="drop"><div><b>${name}</b><small>${desc}</small></div><button ${items.includes(id)?`data-equip="${id}"`:`data-unlock="${id}"`}>${a.equipped===id?'Indossato':items.includes(id)?'Indossa':'Sblocca'}</button></div>`).join('')}</section></div><section class="card"><h2>Il tuo gruppo, lo stesso cielo.</h2><p>Tre amici con account e profilo completato sbloccano le cuffie. Ogni amico conta una volta.</p><div class="meter"><span style="width:${Math.min(100,(account?.referrals||0)/3*100)}%"></span></div><p>${account?.referrals||0} / 3 amici attivati</p><button id="invite-friends" class="button">Copia il tuo invito</button><p id="avatar-status" role="status"></p></section>`}
 function editorialPage(kind){const play=kind==='play',m=editorial();return `<span class="eyebrow">IL METEO CAMBIA I PROGRAMMI</span><h1>${play?'Meteo Play':'Meteo Cinema'}</h1><section class="editorial ${kind}"><span class="eyebrow">${play?'SAVE YOUR GAME':'LA SERATA PRENDE FORMA'}</span><h2 style="margin-top:25px">${play?'Il tuo setup incontra il cielo.':'Fuori cambia scena. Tu scegli il genere.'}</h2><p>${m.kind===kind?e(m.text):play?'Una pausa, un gioco tranquillo e il setup in ordine.':'Non serve aspettare il temporale per una serata sul divano.'}</p><span class="tag">Selezione editoriale · non un’allerta</span></section><div class="quick" style="margin-top:20px">${(play?[['Pausa dal rumore','Una sessione breve, senza inseguire la classifica.'],['Setup al fresco','Segui le indicazioni del produttore per ventilazione e utilizzo.']]:[['Comfort movie','Una storia familiare, senza sorprese.'],['Atmosfera thriller','Un mistero e la pioggia come colonna sonora.']]).map(([a,b])=>`<article class="card"><h2>${a}</h2><p>${b}</p></article>`).join('')}</div><a class="button" href="#assistente">Chiedi all’assistente</a><p class="small">${play?'Il meteo non permette di diagnosticare guasti alla fibra o al computer.':'I titoli e i cataloghi delle piattaforme non sono collegati: nessuna disponibilità viene inventata.'}</p>`}
 function voicesPage(){const ps=(voices?.checkins||[]).filter(p=>p.expires>Date.now());return `<span class="eyebrow">STESSO CIELO</span><h1>Non piove solo sui tuoi programmi.</h1><p>Ascolta la zona. Condividi cinque secondi. I check-in scadono dopo due ore.</p><div class="actions"><button class="button" id="record-voice">Lascia un vocale</button><button id="reload-voices">Aggiorna</button><a class="button" href="#community">Post e foto</a></div><div class="voice-map"><img src="assets/earth.jpg" alt="Mappa geografica mondiale">${ps.map((p,i)=>`<button class="voice-dot" style="left:${(p.lon/10+180)/360*100}%;top:${(90-p.lat/10)/180*100}%" data-voice-focus="${e(p.id)}" aria-label="Ascolta ${e(p.name)} a ${e(p.city)}">${i+1}</button>`).join('')}<span class="map-caption">Zone approssimate · ultimo check-in, non posizione live</span></div>${voiceError?`<p role="alert" class="error">${e(voiceError)}</p>`:''}<div class="voice-grid">${ps.map(p=>`<article class="card voice-card" id="voice-${e(p.id)}"><span class="eyebrow">${e(p.city)}</span><h2>${e(p.name)}</h2><p>${e(p.caption)}</p><audio controls preload="none" src="/api/social/audio/${e(p.id)}" aria-label="Vocale di ${e(p.name)}"></audio><p class="small">${new Date(p.created).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})} · Contenuto non verificato</p><button data-voice-report="${e(p.id)}">Segnala</button>${p.user===state().me?.id?'<button id="delete-voice">Elimina il mio check-in</button>':`<button data-voice-block="${e(p.user)}">Nascondi autore</button>`}</article>`).join('')||`<section class="card"><h2>${voices?'Il primo cielo può essere il tuo.':'Caricamento delle voci…'}</h2><p>Non mostriamo utenti o vocali inventati.</p></section>`}</div><p class="small">Solo la zona arrotondata viene condivisa. Non inserire indirizzi o dati personali nel vocale. Le segnalazioni vengono raccolte; non è garantita una revisione immediata.</p>`}
 async function loadAccount(){if(!state().me)return;try{account=await ctx.api('social/account');if(['home','avatar'].includes(state().route))ctx.render()}catch(err){ctx.toast(err.message)}}
 async function loadVoices(){const id=++loadId;try{const data=await ctx.api('social/checkins');if(id===loadId){voices=data;voiceError=''}}catch(err){voiceError=err.message}if(state().route==='voci')ctx.render()}
 async function generate(){if(!state().weather)return ctx.toast('Attendi il meteo aggiornato.');if(!state().aiReady){variation++;roast=null;ctx.render();return}if(!state().me)return ctx.login();if(busy)return;busy=true;const k=key();$('#generate-roast')?.setAttribute('disabled','');try{const p=state().place,d=await ctx.api('social/roast',{latitude:p.latitude,longitude:p.longitude});if(key()===k){roast=d;roastKey=k;if(['home','roast'].includes(state().route))ctx.render()}}catch(err){ctx.toast(err.message)}finally{busy=false;$('#generate-roast')?.removeAttribute('disabled')}}
 async function shareCard(){const p=state().place,w=state().weather;if(!w)return ctx.toast('Attendi il meteo prima di condividere.');const text=roastKey===key()&&roast?roast.text:fallback(),c=document.createElement('canvas');c.width=1080;c.height=1350;const x=c.getContext('2d');x.fillStyle='#111522';x.fillRect(0,0,c.width,c.height);x.fillStyle='#c8ff63';x.font='bold 44px system-ui';x.fillText('METEOSOCIAL',64,100);x.fillStyle='#c4cee2';x.font='32px system-ui';x.fillText(p.name,64,157,952);if(avatar){const img=new Image();img.src=avatar.capture();await img.decode();x.drawImage(img,230,180,620,600)}x.fillStyle='#f5f7ff';x.font='bold 64px system-ui';let line='',y=840;for(const word of text.split(' ')){const next=line+word+' ';if(x.measureText(next).width>945&&line){x.fillText(line,64,y);y+=79;line=word+' '}else line=next}x.fillText(line,64,y);x.fillStyle='#c8ff63';x.font='30px system-ui';x.fillText(Math.round(w.current.temperature_2m)+'° · '+ctx.description(w.current.weather_code),64,1160,945);x.fillStyle='#b8c3d9';x.font='22px system-ui';x.fillText('Open-Meteo · '+w.current.time.replace('T',' ')+' · '+(roast?.ai?'Testo IA':'Testo editoriale'),64,1220,945);x.fillText(location.origin,64,1280,945);const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!blob)throw Error('Card non disponibile.');const file=new File([blob],'meteosocial-roast.png',{type:'image/png'});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'Il meteo ha preso confidenza.'})}else{const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);ctx.toast('Card scaricata: puoi condividerla nelle tue app.')}}
 async function saveAvatar(update){if(!state().me)return ctx.login();try{await ctx.api('social/avatar',update);await loadAccount()}catch(err){ctx.toast(err.message)}}
 async function startRecorder(){if(!state().me)return ctx.login();clipPlace={...state().place};ctx.modal('Cinque secondi del tuo cielo',`<p>Zona: ${e(clipPlace.name)}. Il vocale sarà pubblico per due ore.</p><button type="button" id="start-record">Registra · massimo 5 secondi</button><p id="record-status" class="record-status" role="status">Microfono spento</p><audio id="record-preview" controls hidden></audio><label class="field"><span>Descrivi il vocale in una frase (obbligatorio)</span><input id="voice-caption" maxlength="160" required placeholder="Qui piove forte, si sente sulle finestre."></label><p class="small">Riascolta prima di pubblicare. Puoi chiudere per annullare.</p>`,async()=>{if(!clip)throw Error('Registra prima un vocale.');await ctx.api('social/checkin',{audio:clip,city:clipPlace.name,latitude:clipPlace.latitude,longitude:clipPlace.longitude,caption:$('#voice-caption').value});clip=null;await loadVoices();ctx.toast('Check-in pubblicato per due ore.');});$('#confirm-dialog').textContent='Pubblica il vocale';$('#confirm-dialog').disabled=true;$('#start-record').onclick=record;
 }
 async function record(){const button=$('#start-record');button.disabled=true;clip=null;if(clipURL){URL.revokeObjectURL(clipURL);clipURL=''}let stream,audio,source,processor,timer,stopped=false;try{stream=await navigator.mediaDevices.getUserMedia({audio:true});if(!$('#dialog').open){stream.getTracks().forEach(t=>t.stop());return}audio=new AudioContext({sampleRate:16000});await audio.resume();const rate=audio.sampleRate,max=rate*5,chunks=[];let count=0;source=audio.createMediaStreamSource(stream);processor=audio.createScriptProcessor(4096,1,1);const stop=async(cancel=false)=>{if(stopped)return;stopped=true;clearTimeout(timer);source.disconnect();processor.disconnect();stream.getTracks().forEach(t=>t.stop());await audio.close();recording=null;if(cancel||!$('#dialog').open)return;if(count<rate/4){$('#record-status').textContent='Audio troppo breve. Riprova.';button.disabled=false;return}const buffer=new ArrayBuffer(44+count*2),v=new DataView(buffer),str=(o,s)=>[...s].forEach((c,i)=>v.setUint8(o+i,c.charCodeAt(0)));str(0,'RIFF');v.setUint32(4,36+count*2,true);str(8,'WAVE');str(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,rate,true);v.setUint32(28,rate*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,count*2,true);let n=44;for(const chunk of chunks)for(const value of chunk){v.setInt16(n,Math.max(-1,Math.min(1,value))*32767,true);n+=2}const bytes=new Uint8Array(buffer);let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));clip=btoa(binary);clipURL=URL.createObjectURL(new Blob([buffer],{type:'audio/wav'}));$('#record-preview').src=clipURL;$('#record-preview').hidden=false;$('#record-status').textContent='Pronto · '+(count/rate).toFixed(1)+' secondi';$('#confirm-dialog').disabled=false;button.disabled=false;button.textContent='Registra di nuovo';};recording=()=>stop(true);processor.onaudioprocess=event=>{if(stopped)return;const chunk=event.inputBuffer.getChannelData(0).slice(0,max-count);chunks.push(chunk);count+=chunk.length;if($('#record-status'))$('#record-status').textContent='Registrazione · '+(count/rate).toFixed(1)+' / 5 s';if(count>=max)stop()};source.connect(processor);processor.connect(audio.destination);timer=setTimeout(()=>stop(),5500)}catch(err){stream?.getTracks().forEach(t=>t.stop());processor?.disconnect();source?.disconnect();await audio?.close().catch(()=>{});if($('#record-status'))$('#record-status').textContent='Microfono non disponibile. Controlla i permessi e riprova.';button.disabled=false}}
 function dispose(){avatarMount++;avatar?.dispose();avatar=null;recording?.();recording=null}
 function bind(){const r=state().route;const host=$('#avatar-stage');if(host){
   const mountId=++avatarMount;
   host.innerHTML='<p>Caricamento del 3D…</p>';
   (async()=>{try{
     const {mountAvatar}=await Promise.reject(Error('Vista avatar ritirata'));
     if(mountId!==avatarMount||!host.isConnected)return;
     avatar?.dispose();
     avatar=mountAvatar(host,account?.avatar?{bald:!!account.avatar.bald,equipped:account.avatar.equipped}:{});
   }catch{if(mountId===avatarMount&&host.isConnected)host.innerHTML='<p>Il 3D non è disponibile su questo dispositivo.</p>'}})();
 }$('#generate-roast')?.addEventListener('click',generate);$('#share-roast')?.addEventListener('click',()=>shareCard().catch(err=>{if(err.name!=='AbortError')ctx.toast('Condivisione non riuscita. Riprova.')}));$('#toggle-hair')?.addEventListener('click',()=>saveAvatar({bald:!(account?.avatar?.bald??1)}));document.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>saveAvatar({equipped:b.dataset.equip}));document.querySelectorAll('[data-unlock]').forEach(b=>b.onclick=async()=>{if(!state().me)return ctx.login();try{await ctx.api('social/unlock',{item:b.dataset.unlock,latitude:state().place.latitude,longitude:state().place.longitude});await loadAccount();ctx.modal('DROP SBLOCCATO',`<div class="unlock-object">✦</div><h2>${b.dataset.unlock==='microphone'?'Microfono da scrivania':'Cuffie streaming'}</h2><p>Lo trovi nel tuo inventario. Premi Indossa per usarlo.</p>`,null)}catch(err){ctx.toast(err.message)}});$('#invite-friends')?.addEventListener('click',async()=>{if(!state().me)return ctx.login();try{await navigator.clipboard.writeText(location.origin+'/?invite='+state().me.id+'#home');ctx.toast('Invito copiato. Tre amici con profilo completato sbloccano le cuffie.')}catch{ctx.toast('Copia non disponibile in questo browser.')}});$('#record-voice')?.addEventListener('click',startRecorder);$('#reload-voices')?.addEventListener('click',loadVoices);document.querySelectorAll('[data-voice-focus]').forEach(b=>b.onclick=()=>document.getElementById('voice-'+b.dataset.voiceFocus)?.scrollIntoView({behavior:'smooth',block:'center'}));document.querySelectorAll('[data-voice-report]').forEach(b=>b.onclick=()=>ctx.modal('Segnala il vocale','<label class="field"><span>Motivo</span><input id="voice-reason" required maxlength="200"></label>',async()=>{await ctx.api('social/report',{id:b.dataset.voiceReport,reason:$('#voice-reason').value});ctx.toast('Segnalazione ricevuta. Non è garantita una revisione immediata.')}));document.querySelectorAll('[data-voice-block]').forEach(b=>b.onclick=async()=>{try{await ctx.api('link',{kind:'block',target:b.dataset.voiceBlock,active:true});await loadVoices()}catch(err){ctx.toast(err.message)}});$('#delete-voice')?.addEventListener('click',()=>ctx.modal('Elimina il tuo check-in','<p>Il vocale non sarà più disponibile sulla mappa.</p>',async()=>{await ctx.api('social/delete',{});await loadVoices()}));if(r==='voci'&&!voices&&!voiceError)loadVoices();if(state().me&&!account&&!busy){busy=true;loadAccount().finally(()=>busy=false)}}
 $('#dialog').addEventListener('close',()=>{recording?.();clip=null;if(clipURL){URL.revokeObjectURL(clipURL);clipURL=''}});
 setInterval(()=>{if(state().route==='voci')loadVoices()},60000);
 return {home,avatarPage,voicesPage,editorialPage,bind,dispose,refresh(){roast=null;if(['home','roast'].includes(state().route))ctx.render()},async onIdentity(){account=null;const invite=new URLSearchParams(location.search).get('invite');if(invite&&state().me){try{await ctx.api('social/referral',{inviter:invite});history.replaceState(null,'',location.pathname+location.hash)}catch{}}await loadAccount()}};
}
